{
  "story": "For standard binary AdaBoost, start with four equally weighted examples and a learning rate of one. A fixed weak learner correctly classifies A, B, and C but misses D. Advance to the normalized weight update. D gains influence, correctly classified examples lose influence, and total weight stays one.",
  "aha": {
    "stateId": "normalized-update",
    "observation": "The misclassified example gains normalized weight, giving it more influence when fitting the next weak learner."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "update-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell with explanation and navigation instructions above the experiment. Show two discrete states, never elapsed time. Parameter-control budget: zero; navigation and reset are separate. Keep progress on this rail. Reference captures show the aha state.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "training-examples",
      "kind": "fixed-picture",
      "presentation": "Use the canonical algorithm/collection arrangement: four fixed example regions in one row. Keep names, actual labels, predictions, and correctness visible. Bind emphasis to active region IDs. Predictions remain fixed throughout the update.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "weight-comparison",
      "kind": "value-readout",
      "presentation": "Place an aligned weight table below the picture, matching example names. Initially show starting weights; afterward show before → after in each example row. This persistent comparison replaces a previous-state ghost. Weights are dimensionless, share the range zero to one, and use exact fractions without rounding. Compute updates from the displayed predictions using standard binary AdaBoost and the declared learning rate. Keep all numerical evidence here.",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "active-example-explanation",
      "kind": "active-callout",
      "presentation": "Anchor text beside the target region without covering labels. Callout text identifies the affected example, not numerical values. Render reason as the bound status line below the experiment.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    }
  ],
  "controls": [
    {
      "id": "update-state",
      "kind": "index",
      "label": "Training-weight update",
      "items": "variant.states",
      "presentation": "Use Previous and Next, retaining those names when disabled at boundaries. Default to the first state; bounds are the first and last states. Each action changes the index by one. Every state persists until the learner acts, including the aha state. Provide accessible names, visible focus, and keyboard operation."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Provide an accessible name, visible focus, and keyboard operation."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "One binary AdaBoost weight update",
        "regions": [
          {
            "id": "A",
            "label": "A",
            "values": [
              "Actual: positive",
              "Predicted: positive",
              "Correct"
            ]
          },
          {
            "id": "B",
            "label": "B",
            "values": [
              "Actual: negative",
              "Predicted: negative",
              "Correct"
            ]
          },
          {
            "id": "C",
            "label": "C",
            "values": [
              "Actual: positive",
              "Predicted: positive",
              "Correct"
            ]
          },
          {
            "id": "D",
            "label": "D",
            "values": [
              "Actual: negative",
              "Predicted: positive",
              "Misclassified"
            ]
          }
        ],
        "links": [],
        "states": [
          {
            "id": "equal-weights",
            "label": "Before update",
            "short": "Equal weights",
            "sentence": "D is the missed example; its training weight initially matches those of correctly classified A, B, and C.",
            "why": "The weak learner has finished predicting; these are the weights before AdaBoost updates them.",
            "active": [
              "A",
              "B",
              "C",
              "D"
            ],
            "calloutRegion": "D",
            "readouts": [
              {
                "id": "weight-A",
                "label": "A weight",
                "value": "1/4"
              },
              {
                "id": "weight-B",
                "label": "B weight",
                "value": "1/4"
              },
              {
                "id": "weight-C",
                "label": "C weight",
                "value": "1/4"
              },
              {
                "id": "weight-D",
                "label": "D weight",
                "value": "1/4"
              },
              {
                "id": "total-weight",
                "label": "Total normalized weight",
                "value": "1"
              }
            ]
          },
          {
            "id": "normalized-update",
            "label": "After update",
            "short": "D gains influence",
            "sentence": "D gains influence; correctly classified A, B, and C lose influence.",
            "why": "AdaBoost increases the missed example’s relative weight and renormalizes; the next weak learner trains using these updated weights.",
            "active": [
              "D"
